const s="lyceum64_active_test";class n{static instance;constructor(){}static getInstance(){return n.instance||(n.instance=new n),n.instance}startTest(t){const e=crypto.randomUUID(),r={...t,id:e};return localStorage.setItem(s,JSON.stringify(r)),e}getActiveTest(){try{const t=localStorage.getItem(s);return t?JSON.parse(t):null}catch{return null}}hasActiveTest(){return this.getActiveTest()!==null}updateProgress(t){const e=this.getActiveTest();if(!e)return;const r={...e,...t};localStorage.setItem(s,JSON.stringify(r))}completeTest(){localStorage.removeItem(s)}abandonTest(){localStorage.removeItem(s)}getTimeSinceStart(){const t=this.getActiveTest();if(!t)return null;const e=new Date(t.startedAt);return Math.floor((Date.now()-e.getTime())/1e3)}isTestExpired(t){const e=this.getTimeSinceStart();return e===null?!1:e>=t}}const a=()=>n.getInstance();export{a as g};
